const terms = (query) => query.toLowerCase().split(/[^\p{L}\p{N}_$.#-]+/u).map((term) => term.replace(/^[.#-]+|[.-]+$/gu, ""))
    .filter((term) => term.length > 2 && !["and", "the", "for", "or", "not"].includes(term));
